/**
 * Aplica un color de fondo a una celda específica y actualiza su estado visual.
 * @param {string} key - La clave de la celda (ej: "A1").
 * @param {string} color - Código hexadecimal del color (#RRGGBB).
 */
function setColor(key, color) {
    const cellElement = document.querySelector(`[data-cell="${key}"]`);
    if (!cellElement) return;

    // 1. Aplicar el estilo al elemento DOM
    cellElement.style.backgroundColor = color;
    cellElement.classList.add('color-applied'); // Clase para mantener la transición si se usa CSS más avanzado

