                event.preventDefault();

                // Simular la pérdida de foco para disparar la lógica de guardado
                handleCellChange(event); 
            }
        });

         // Opcional: Agregar un listener simple de click para que, si el estado está vacío, se muestre algo al hacer clic.
         cell.addEventListener('click', () => {
             if (estado.cells[cell.dataset.cell] === "") {
                 cell.textContent = ""; // Asegurar que esté visualmente limpio antes de editar
             } else {
                // Si ya hay contenido, lo render() se encargará. Esto solo sirve para asegurar la visibilidad al hacer click en una celda vacía.
             }
         });
    });

    // --- NUEVO CONTROL: Manejador de eventos para el selector de color ---
    const colorPicker = document.getElementById('colorPickerInput');
    if (colorPicker) {
        colorPicker.addEventListener('input', (event) => {
            const selectedColor = event.target.value;
            // Determinar la celda activa/enfocada para aplicar el color
            let activeCell = document.querySelector('[contenteditable="true"]:focus');

            if (activeCell && activeCell.dataset.cell) {
                const key = activeCell.dataset.cell;
                setColor(key, selectedColor);
            } else if (!activeCell) {
                // Si no hay nada enfocado, no hacemos nada o mostramos un mensaje.
            }
        });
    }
