function clearSelectedColumnContent() {
    const selectedCol = estado.selectedColumn;
    if (!selectedCol) return;

    if (!confirm(`¿Estás seguro de que quieres borrar TODO el contenido de la columna ${selectedCol}?`)) {
        return;
    }

    // 1. Limpiar visualmente todas las celdas
    document.querySelectorAll(`[data-cell^="${selectedCol}"][contenteditable="true"]`).forEach(cell => {
        cell.textContent = '';
        cell.removeAttribute('style'); // Remover cualquier estilo de fondo aplicado previamente
    });

    // 2. Limpiar el estado interno (la fuente de verdad)
    for (const key in estado.cells) {
        if (key.startsWith(selectedCol)) {
            estado.cells[key] = '';
        }
    }

    // 3. Redibujar para asegurar que el contenido vacío se respete en render()
    render();
}
