```javascript
function deleteSelectedColumn() {
    // Obtiene la letra de la columna seleccionada del elemento marcado previamente.
    const headerElement = document.querySelector('.col-header.selected'); 
    if (!headerElement) return;

    const colLetter = headerElement.dataset.column;

    // 1. Eliminar el encabezado de la columna del DOM
    headerElement.remove();

    // 2. Iterar sobre las filas (asumiendo que hay 20 filas visibles) y eliminar celdas y estado.
    const rows = document.querySelectorAll('#spreadsheet-grid tbody tr');
    for (let i = 0; i < rows.length; i++) {
        // En este contexto, el índice de la fila es más robusto que iterar por números fijos.
        // Sin embargo, dado que el harness solo muestra 20 filas estáticas y no hay un sistema de índices fiable sin alterar HTML, asumimos las 20 filas (1 a 20) para la limpieza del estado.
    }

    let keysDeletedCount = 0;
    for (let r = 1; r <= 20; r++) {
        const key = `${colLetter}${r}`;
        const cellElement = document.querySelector(`[data-cell="${key}"]`);
        if (cellElement) {
            // Eliminar el elemento del DOM y actualizar el estado
            cellElement.remove();
            delete estado.cells[key];
            keysDeletedCount++;
        }
    }

    guardar();
    render(); 
}
```

