function clearSelectedColumnContent() {
    const headerElement = document.querySelector('.col-header.selected'); 
    if (!headerElement) return;

    const colLetter = headerElement.dataset.column;

    // Limpiar el estado para todas las celdas de esta columna (A1, A2, ..., A20).
    let keysClearedCount = 0;
    for (let r = 1; r <= 20; r++) {
        const key = `${colLetter}${r}`;
        // Actualizar estado a vacío si existía contenido.
        if (estado.cells[key] !== undefined) {
            updateCellState(key, '');
            keysClearedCount++;
        }
    }

