 * @param {string} letter - La letra de la columna (ej: "A").
 * @param {string} color - El color hexadecimal o nombre CSS.
 */
function applyColumnBackground(letter, color) {
    // Selector para encontrar todas las celdas cuyo atributo data-cell empiece con esta letra
    const selector = `#spreadsheet-grid td[data-cell^="${letter}"]`;
    const cells = document.querySelectorAll(selector);

    cells.forEach(cell => {
        // Aplicar el fondo directamente al estilo para asegurar la visibilidad en cualquier entorno de prueba
        cell.style.backgroundColor = color; 
    });
}
