 */
function calculateValue(formulaString) {
    if (!formulaString || !formulaString.startsWith('=')) return formulaString;

    let formula = formulaString.substring(1);
    // Simple parser: Solo soporta SUMA de rango para este ejemplo avanzado.
    if (formula.toUpperCase().startsWith("SUM")) {
        const match = formula.match(/SUM\((.*)\)/i);
        if (match && match[1]) {
            let rangeContent = match[1]; // e.g., "A1:A5"
            return calculateSumRange(rangeContent);
        }
    }
    // Si no es una fórmula reconocida, devuelve el valor como texto.
    return formulaString;
}

/**
 * Calcula la suma de un rango de celdas (ej. A1:A5).
 */
function calculateSumRange(rangeContent) {
    const [startCellKey, endCellKey] = rangeContent.split(':');
    if (!startCellKey || !endCellKey) return "ERROR";

    // Determinar coordenadas de inicio y fin (simplificado para este alcance)
    const startColLetter = getColumnLetter(startCellKey);
    const startRowNumber = parseInt(startCellKey.substring(1));

    const endColLetter = getColumnLetter(endCellKey);
    const endRowNumber = parseInt(endCellKey.substring(1));

    let totalSum = 0;
    let cellsToSum = [];

    // Lógica simplificada para iterar entre las columnas y filas de un rango rectangular (A1:B2)
    // Asumimos que el formato es siempre A_RANGO : B_RANGO
    const startColIndex = getColumnLetterIndex(startColLetter);
    const endColIndex = getColumnLetterIndex(endColLetter);

    for (let i = startColIndex; i <= endColIndex; i++) {
        const colLetter = getColumnLetterFromIndex(i);
        // El número de filas a sumar debe ser el máximo de los dos rangos. Usamos el inicio y fin del rango dado.
        const maxRows = Math.max(startRowNumber, endRowNumber); 

        for (let r = startRowNumber; r <= endRowNumber; r++) {
            const key = `${colLetter}${r}`;
            if (estado.cells[key] !== undefined) {
                const value = parseFloat(estado.cells[key]);
                if (!isNaN(value)) {
                    totalSum += value;
                }
            }
        }
    }

    return totalSum === 0 ? 0 : totalSum.toFixed(2);
}


/**
 * Obtiene la letra de columna a partir de una clave (ej. A1 -> A).
 */
function getColumnLetter(key) {
    if (!key || key.length < 2) return null;
    return key.substring(0, 1).toUpperCase(); // Asume que siempre es la primera letra
}

/**
 * Obtiene el índice numérico de una letra de columna (A=0, B=1, etc.).
 */
function getColumnLetterIndex(letter) {
    const code = letter.toUpperCase().charCodeAt(0);
    return code - 'A'.charCodeAt(0);
}

/**
 * Obtiene la letra de columna a partir de un índice numérico (0 -> A).
 */
function getColumnLetterFromIndex(index) {
    return String.fromCharCode('A'.charCodeAt(0) + index);
}


