```javascript
// ===== CONTROLES: conectar() se llama UNA sola vez. Cada evento: llama a la LÓGICA, después guardar() y render(). =====
function conectar() {
    /**
     * Manejador de cambios que actualiza el estado cuando una celda pierde foco o recibe Enter.
     * @param {Event} event - El objeto de evento (si se trata de interacción del usuario).
     * @param {string | null} explicitKey - La clave de la celda si el cambio es programático.
     * @param {string | null} explicitValue - El valor si el cambio es programático.
     */
    const handleCellChange = (event, explicitKey = null, explicitValue = null) => {
        let cellElement;
        let key;
        let newValue;

        if (event && event.target) {
            cellElement = event.target;
            key = cellElement.dataset.cell;
            // Si es un evento de usuario, el valor está en textContent.
            newValue = cellElement.textContent; 
        } else if (explicitKey && explicitValue !== null) {
            // Modo programático (usado para actualizaciones masivas como borrar una columna).
            key = explicitKey;
            newValue = explicitValue;
            cellElement = document.querySelector(`[data-cell="${key}"]`); // Necesario si vamos a simular el flujo de evento
        } else {
            return;
        }

        // 1. Actualizar Lógica (Estado)
        updateCellState(key, newValue);

        // 2. Guardar y Redibujar
        guardar();
        render();
    };


    // Seleccionar todas las celdas de datos para adjuntar los listeners necesarios
    const editableCells = document.querySelectorAll('#spreadsheet-grid td[contenteditable="true"]');

    editableCells.forEach(cell => {
        // 1. Manejar salida de foco (focusout)
        // Usamos focusout porque el blur no burbujea y es lo más cercano a perder el foco en un evento manejable.
        cell.addEventListener('focusout', (event) => handleCellChange(event));

        // 2. Manejar la tecla Enter (keydown)
        cell.addEventListener('keydown', (event) => {
            if (event.key === 'Enter') {
                // Prevenir el comportamiento por defecto (que podría añadir un salto de línea o enviar un formulario)
                event.preventDefault();

                // Simular la pérdida de foco para disparar la lógica de guardado
                handleCellChange(event); 
            }
        });

         // Opcional: Agregar un listener simple de click para que, si el estado está vacío, se muestre algo al hacer clic.
         cell.addEventListener('click', () => {
             if (estado.cells[cell.dataset.cell] === "") {
                 cell.textContent = ""; // Asegurar que esté visualmente limpio antes de editar
             } else {
                // Si ya hay contenido, lo render() se encargará. Esto solo sirve para asegurar la visibilidad al hacer click en una celda vacía.
             }
         });
    });

    // Exponer el manejador de cambios para uso externo (ej: función de borrar columna)
    window._handleSpreadsheetCellChange = handleCellChange;
}

/**
 * El harness llamará a cargar(), y luego debe llamar a conectar() y render().
 */
