function conectar() {
    // Función manejadora de cambios en celdas (focusout o Enter)
    const handleCellChange = (event) => {
        let cellElement = event.target;
        if (!cellElement || !cellElement.dataset.cell) return;

        const key = cellElement.dataset.cell;
        // Obtener el contenido actual del elemento editable
        let newValue = cellElement.textContent; 

        // 1. Actualizar Lógica (Estado)
        updateCellState(key, newValue);

        // 2. Guardar y Redibujar
        guardar();
        render();
    };


    // --- Listeners para la selección de columnas ---
    const colHeaders = document.querySelectorAll('.col-header');
    colHeaders.forEach(header => {
        header.addEventListener('click', (e) => {
            let columnLetter = e.currentTarget.dataset.column;
            if (!columnLetter) return;

            // Actualizar el estado de la columna seleccionada
            estado.selectedColumn = columnLetter;
            console.log(`Columna seleccionada: ${columnLetter}`); 
        });
    });


    // Seleccionar todas las celdas de datos para adjuntar los listeners necesarios
    const editableCells = document.querySelectorAll('#spreadsheet-grid td[contenteditable="true"]');

    editableCells.forEach(cell => {
        // 1. Manejar salida de foco (focusout)
        cell.addEventListener('focusout', handleCellChange);

        // 2. Manejar la tecla Enter (keydown)
        cell.addEventListener('keydown', (event) => {
            if (event.key === 'Enter') {
                event.preventDefault();
                handleCellChange(event); 
            }
        });
    });

    // Listener global para manejar el evento de "vaciar" la columna (Delete/Backspace), si hay una columna seleccionada y no se está editando una celda.
    document.addEventListener('keydown', (event) => {
        const isDeleteOrBack = event.key === 'Delete' || event.key === 'Backspace';

        // Solo actuar si: 1. Hay una columna seleccionada, 2. La tecla es Delete/Backspace, y 3. No estamos en un campo editable activo (para evitar borrar contenido intencionalmente).
        const isFocusInEditableCell = document.activeElement && document.activeElement.closest('[contenteditable="true"]');

        if (isDeleteOrBack && estado.selectedColumn && !isFocusInEditableCell) {
            event.preventDefault(); // Prevenir la acción por defecto del navegador
            clearColumnContent(estado.selectedColumn);
        }
    });
}
