function selectRow(rowIndex) {
    // 1. Deseleccionar la fila actual visualmente
    const allDataRows = document.querySelectorAll('.data-row');
    allDataRows.forEach(row => row.classList.remove('selected'));

    // 2. Determinar el índice y elemento del header de la fila seleccionada
    const selectedRowElement = document.querySelector(`.data-row[data-row-index="${rowIndex}"]`);
    if (selectedRowElement) {
        // 3. Seleccionar visualmente
        selectedRowElement.classList.add('selected');
        estado.selectedRow = rowIndex;

        // 4. Habilitar/Deshabilitar controles basados en la selección
        const controlsDisabled = !rowIndex;
        document.getElementById('delete-row-btn').disabled = controlsDisabled;
        document.getElementById('clear-content-btn').disabled = controlsDisabled;
        document.getElementById('color-background-btn').disabled = controlsDisabled;

        // 5. Forzar redibujado para asegurar que el estado visual esté correcto (aunque no haya cambiado la data)
        render(); 
    } else {
        estado.selectedRow = null;
        // Deshabilitar controles si la fila no existe o no se pudo seleccionar
        document.getElementById('delete-row-btn').disabled = true;
        document.getElementById('clear-content-btn').disabled = true;
        document.getElementById('color-background-btn').disabled = true;
    }
}
