```js
function deleteSelectedRow() {
    const rowIndexToDelete = estado.selectedRow;
    if (!rowIndexToDelete) return;

    // 1. Recopilar todas las claves de la fila a eliminar del estado
    let keysToDelete = [];
    const cellsInRow = document.querySelectorAll(`.data-row[data-row-index="${rowIndexToDelete}"] td`);
    cellsInRow.forEach(cell => {
        keysToDelete.push(cell.dataset.cell);
    });

    // 2. Eliminar del estado interno
    keysToDelete.forEach(key => delete estado.cells[key]);

    // 3. Eliminar la fila del DOM
    const rowElement = document.querySelector(`.data-row[data-row-index="${rowIndexToDelete}"]`);
    if (rowElement) {
        rowElement.remove();
    }

    // 4. Resetear y guardar estado visual
    estado.selectedRow = null;
    guardar();
    render();
    updateControls(null); // Deshabilitar controles después de la eliminación
}
