function clearSelectedRowContent() {
    const rowIndexToClear = estado.selectedRow;
    if (!rowIndexToClear) return;

    // 1. Recopilar todas las celdas y claves de la fila seleccionada
    let keysToClear = [];
    const cellsInRow = document.querySelectorAll(`.data-row[data-row-index="${rowIndexToClear}"] td`);
    cellsInRow.forEach(cell => {
        const key = cell.dataset.cell;
        if (estado.cells[key] !== "") {
            keysToClear.push(key);
        }
    });

    // 2. Limpiar el estado interno y actualizar los valores de la celda en el DOM
    keysToClear.forEach(key => {
        updateCellState(key, "");
    });

    // 3. Guardar y Redibujar (esto limpiará visualmente las celdas)
    guardar();
    render();
}
