function setupRowControls() {
    // Seleccionar todos los encabezados de fila (los números)
    const rowHeaders = document.querySelectorAll('.row-header');

    rowHeaders.forEach(header => {
        // Adjuntar el evento de click al header
        header.addEventListener('click', (event) => {
            // Prevenir que se disparen otros eventos si hay alguno en los padres o hermanos
            event.stopPropagation(); 

            const rowNumber = event.currentTarget.dataset.row;
            const rowElement = document.querySelector(`.data-row[data-row-number="${rowNumber}"]`);

            if (rowElement) {
                // Deseleccionar cualquier fila previamente seleccionada
                document.querySelectorAll('.data-row').forEach(r => r.classList.remove('selected-row'));

                // Seleccionar la nueva fila y actualizar el estado visual
                rowElement.classList.add('selected-row');

                // Actualizar Controles de UI
                const controlsDiv = document.getElementById('row-controls');
                document.getElementById('selected-row-number').textContent = rowNumber;
                controlsDiv.style.display = 'block';

                // Limpiar cualquier clase de coloración previa en las celdas al seleccionar (opcional, pero bueno para el UX)
                const cells = rowElement.querySelectorAll('td');
                cells.forEach(cell => cell.classList.remove('highlight-background'));
            }
        });
    });

    // 1. Evento de Borrar Fila
    document.getElementById('btn-delete-row')?.addEventListener('click', handleDeleteRow);

    // 2. Evento de Limpiar Contenido
    document.getElementById('btn-clear-row')?.addEventListener('click', handleClearRow);

    // 3. Evento de Colorizar Fila
    document.getElementById('btn-colorize-row')?.addEventListener('click', handleColorizeRow);
}
