### FUNCION: deleteSelectedRow
```javascript
function deleteSelectedRow() {
    if (isNaN(estado.selectedRow)) return;

    const rowIndex = estado.selectedRow;
    let cellsToDelete = [];
    let cellKeysToRemove = [];

    // 1. Identificar claves y elementos a borrar del estado/DOM
    document.querySelectorAll(`.row-header[data-row="${rowIndex}"] + td[contenteditable="true"]`).forEach(cellElement => {
        const key = cellElement.dataset.cell;
        cellsToDelete.push(cellElement);
        cellKeysToRemove.push(key);
    });

    // 2. Borrar datos del estado
    cellKeysToRemove.forEach(key => {
        delete estado.cells[key];
    });

    // 3. Eliminar elementos DOM (filas completas)
    const rowElement = document.querySelector(`.row-header[data-row="${rowIndex}"]`).closest('tr');
    if (rowElement) {
        rowElement.remove();
    }

    // 4. Actualizar estado y redibujar
    estado.selectedRow = NaN; // Deseleccionar la fila
    guardar();
    render();
    updateControlsUI();
}
