function clearSelectedRow() {
    if (isNaN(estado.selectedRow)) return;

    const rowIndex = estado.selectedRow;
    let keysToClear = [];

    // 1. Identificar todas las claves de la fila seleccionada
    document.querySelectorAll(`.row-header[data-row="${rowIndex}"] + td[contenteditable="true"]`).forEach(cellElement => {
        const key = cellElement.dataset.cell;
        keysToClear.push(key);
    });

    // 2. Limpiar el estado de todas las celdas en esa fila
    keysToClear.forEach(key => {
        estado.cells[key] = '';
    });

    // 3. Guardar y redibujar para reflejar los vacíos
    guardar();
    render();
}
