    const clearButton = document.getElementById('clear-button');

    if (isNaN(selectedRow)) {
        // No hay fila seleccionada
        document.getElementById('color-picker').value = '#ffffff'; // Reset color picker
        document.getElementById('row-background-display').textContent = 'Fondo: #ffffff';
        controlsPanel.style.display = 'none';
        deleteButton.disabled = true;
        clearButton.disabled = true;
    } else {
        // Hay fila seleccionada, asegurar que los controles estén activos y reflejando el color actual
        const currentColor = estado.backgroundColor || '#ffffff';
        document.getElementById('color-picker').value = currentColor;
        document.getElementById('row-background-display').textContent = `Fondo: ${currentColor}`;
        controlsPanel.style.display = 'flex';
        deleteButton.disabled = false;
        clearButton.disabled = false;
    }
}
