function handleRowContextMenu(event, rowNumber) {
    event.preventDefault(); // Previene el menú contextual por defecto del navegador

    const container = document.getElementById('spreadsheet-container');

    // 1. Limpiar cualquier menú existente y deseleccionar visualmente
    document.querySelectorAll('.row-header').forEach(el => el.classList.remove('selected'));
    if (window._contextMenu) {
        window._contextMenu.remove();
    }

    const menu = document.createElement('div');
    menu.className = 'context-menu'; // Asumimos que agregaremos esta clase en CSS o que es suficiente para la estructura JS
    menu.style.position = 'absolute';
    menu.style.left = `${event.clientX}px`;
    menu.style.top = `${event.clientY}px`;
    menu.style.zIndex = '1000';

    // Contenido del menú
    const items = [
        { text: "Borrar Fila", action: () => deleteRow(rowNumber) },
        { text: "Limpiar Contenido de la Fila", action: () => clearRowContent(rowNumber) },
        { text: "Cambiar Color de Fondo...", action: (e) => {
            const color = prompt("Ingrese el código hexadecimal del color (#RRGGBB):");
            if (color && /^#[0-9A-Fa-f]{6}$/.test(color)) {
                setBackgroundColor(rowNumber, color);
            } else if (color !== null) {
                alert('Formato de color inválido. Debe ser #RRGGBB.');
            }
        }}
    ];

    items.forEach(item => {
        const button = document.createElement('button');
        button.textContent = item.text;
        button.onclick = (e) => {
            // Ejecutar la acción y cerrar el menú después de un pequeño retraso para que se procesen los eventos
            setTimeout(() => {
                item.action();
                menu.remove();
                window._contextMenu = null;
            }, 10);
        };
        menu.appendChild(button);
    });

    document.body.appendChild(menu);
    window._contextMenu = menu; // Guardar referencia para limpieza
}
