function conectar() {
    // --- Lógica de Manejo de Cambios de Celdas (EXISTENTE) ---
    const handleCellChange = (event) => {
        let cellElement = event.target;
        if (!cellElement || !cellElement.dataset.cell) return;

        const key = cellElement.dataset.cell;
        // Obtener el contenido actual del elemento editable
        let newValue = cellElement.textContent; 

        // 1. Actualizar Lógica (Estado)
        updateCellState(key, newValue);

        // 2. Guardar y Redibujar
        guardar();
        render();
    };


    // Seleccionar todas las celdas de datos para adjuntar los listeners necesarios
    const editableCells = document.querySelectorAll('#spreadsheet-grid td[contenteditable="true"]');

    editableCells.forEach(cell => {
        // 1. Manejar salida de foco (focusout)
        cell.addEventListener('focusout', handleCellChange);

        // 2. Manejar la tecla Enter (keydown)
        cell.addEventListener('keydown', (event) => {
            if (event.key === 'Enter') {
                event.preventDefault();
                handleCellChange(event); 
            }
        });

         // Opcional: Agregar un listener simple de click para que, si el estado está vacío, se muestre algo al hacer clic.
         cell.addEventListener('click', () => {
             if (estado.cells[cell.dataset.cell] === "") {
                 cell.textContent = ""; 
             } else {
                // Si ya hay contenido, lo render() se encargará. Esto solo sirve para asegurar la visibilidad al hacer hacer click en una celda vacía.
             }
         });
    });

    // --- NUEVA LÓGICA DE FILAS Y CONTEXTO (R7) ---
    const rowHeaders = document.querySelectorAll('.row-header');
    let selectedRowElement = null;

    // 1. Listener de Clic para Selección Visual y Contextual
    rowHeaders.forEach(header => {
        header.addEventListener('click', (event) => {
            const rowNumber = event.currentTarget.dataset.row;
            if (!rowNumber) return;

            // Deseleccionar el elemento previamente seleccionado
            if (selectedRowElement) {
                selectedRowElement.classList.remove('selected');
            }

            // Seleccionar visualmente el nuevo elemento y guardar referencia
            event.currentTarget.classList.add('selected');
            selectedRowElement = event.currentTarget;
        });
    });

    // 2. Listener de Menú Contextual (Right Click) en toda la columna de encabezados de fila
    const rowHeaderContainer = document.querySelector('.row-header').closest('thead tr');
    if (rowHeaderContainer) {
         rowHeaderContainer.addEventListener('contextmenu', (event) => {
            // Verificamos si el click ocurrió sobre un .row-header para determinar la fila
            const target = event.target.closest('.row-header');
            if (target) {
                handleRowContextMenu(event, target.dataset.row);
            } else if (!event.target.closest('.context-menu')) {
                // Si se hace clic en un área no manejada o si el menú ya está abierto por otro mecanismo
                // simplemente evitamos el contexto menu default del navegador.
                 event.preventDefault();
            }
        });
    }

}
