### FUNCION: toggleVisibility
```js
function toggleVisibility(type, id) {
    if (type === 'row') {
        const rowSelector = `.row-header[data-row="${id}"] ~ td`;
        const rowCells = document.querySelectorAll(`tr[data-row="${id}"]`);

        // Determinar el estado actual de la visibilidad del contenedor padre
        let isHidden = rowCells[0].style.display === 'none';

        if (isHidden) {
            // Mostrar: Restaurar estilos por defecto
            document.querySelectorAll(`tr[data-row="${id}"]`).forEach(r => r.style.display = '');
            // También restauramos la visibilidad del propio header de fila si lo ocultamos previamente (aunque no debería pasar)
            const rowHeaderEl = document.querySelector(`.row-header[data-row="${id}"]`);
            if (rowHeaderEl) rowHeaderEl.style.display = '';

        } else {
            // Ocultar: Aplicar display: none a toda la fila y su header
            document.querySelectorAll(`tr[data-row="${id}"]`).forEach(r => r.style.display = 'none');
             const rowHeaderEl = document.querySelector(`.row-header[data-row="${id}"]`);
            if (rowHeaderEl) rowHeaderEl.style.display = 'none';
        }

    } else if (type === 'column') {
        let columnSelector = `th[data-column="${id}"]`;
        const headerCell = document.querySelector(columnSelector);

        // 1. Ocultar/Mostrar el encabezado de columna principal (thead)
        if (headerCell) {
            let isHidden = headerCell.style.display === 'none';
            if (isHidden) {
                headerCell.style.display = ''; // Mostrar
            } else {
                headerCell.style.display = 'none'; // Ocultar
            }
        }

        // 2. Iterar sobre todas las filas para ocultar/mostrar las celdas de datos
        const allRows = document.querySelectorAll('#spreadsheet-grid tbody tr');
        allRows.forEach(row => {
            // Buscar la celda en esta fila que corresponde a la columna actual
            const cellToToggle = row.querySelector(`td[data-cell*="${id}"]`); 
            if (cellToToggle) {
                let isHidden = cellToToggle.style.display === 'none';

                if (isHidden) {
                    // Mostrar: Restaurar estilos por defecto
                    cellToToggle.style.display = '';
                } else {
                    // Ocultar: Aplicar display: none
                    cellToToggle.style.display = 'none';
                }
            }
        });
    }

    // Nota sobre el estado interno: No actualizamos el `estado` porque la visibilidad es puramente de presentación (DOM/CSS).
    // Solo manipulamos el DOM directamente para reflejar el cambio en la UI.
}
