  allRows.forEach(row => {
      const rowNumber = row.querySelector('.row-header').dataset.row;
      if (estado.hiddenRows && estado.hiddenRows.has(parseInt(rowNumber))) {
          row.classList.add('hidden');
      } else {
          row.classList.remove('hidden');
      }
  });

  const allColHeaders = document.querySelectorAll('.col-header, .corner-header');
  allColHeaders.forEach(th => {
      const colLetter = th.dataset.column;
      if (estado.hiddenColumns && estado.hiddenColumns.has(colLetter)) {
